// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, IProduct} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    MockController mc;
    MockOracle mo;

    function setUp() public {
        c = new Product();
    }

    function testFuzz_property(address ownerAddr, address nonOwnerAddr, uint256 rawMaintenance) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(nonOwnerAddr != address(0));
        vm.assume(ownerAddr != nonOwnerAddr);
        mc = new MockController();
        mo = new MockOracle();
        vm.assume(ownerAddr != address(c) && nonOwnerAddr != address(c));
        vm.assume(ownerAddr != address(mc) && nonOwnerAddr != address(mc));
        vm.assume(ownerAddr != address(mo) && nonOwnerAddr != address(mo));

        // initialize the product from the controller (as C expects)
        PayoffDefinition memory pd;
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: pd,
            oracle: IOracleProvider(address(mo)),
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e24),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });
        vm.prank(address(mc));
        c.initialize(info);
        mc.setCoordinatorOwner(ownerAddr);

        UFixed18 newMaintenance = UFixed18.wrap(bound(rawMaintenance, 0, 1e18));

        // RULE: the coordinator owner can update maintenance; a non-owner cannot
        bool okOwner = true;
        vm.prank(ownerAddr);
        try c.updateMaintenance(newMaintenance) { okOwner = true; } catch { okOwner = false; }

        bool okNonOwner = false;
        vm.prank(nonOwnerAddr);
        try c.updateMaintenance(newMaintenance) { okNonOwner = true; } catch { okNonOwner = false; }

        assertTrue(okOwner && !okNonOwner);
    }
}

contract MockController {
    address public coordinatorOwner;

    function setCoordinatorOwner(address a) external { coordinatorOwner = a; }

    function isProduct(IProduct) external pure returns (bool) { return true; }

    function coordinatorFor(IProduct) external pure returns (uint256) { return 1; }

    function owner(uint256) external view returns (address) { return coordinatorOwner; }

    function paused() external pure returns (bool) { return false; }
}

contract MockOracle {
    function _ov() internal pure returns (IOracleProvider.OracleVersion memory v) {
        v.version = 0;
        v.timestamp = 0;
        v.price = Fixed18.wrap(0);
    }

    function sync() external pure returns (IOracleProvider.OracleVersion memory) { return _ov(); }

    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) { return _ov(); }

    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) { return _ov(); }
}
